SELECT
  AVG(
    ROUND((
      STRFTIME('%Y', T1.final_game) - STRFTIME('%Y', T1.debut)
    ), 2) + ROUND((
      STRFTIME('%m', T1.final_game) - STRFTIME('%m', T1.debut)
    ) / 12.0, 2) + ROUND((
      STRFTIME('%d', T1.final_game) - STRFTIME('%d', T1.debut)
    ) / 365.0, 2)
  ) AS average_career_span
FROM player AS T1
